      "chain": "C1",
      "severity_class": "S3",
      "reason": "Tube rupture in EA-425B releases flammable hydrocarbons (propane, propylene, C4-heavies) to occupied outdoor Olefins unit (LOC-OLEFINS-UNIT), causing significant release with potential fire/explosion leading to single fatality or serious injuries on site."
    },
    {
      "chain": "C2",
      "severity_class": "S2",
      "reason": "Flammable hydrocarbon-water mixture discharged to quench utility UT-QW (LOC-QUENCH-LOOP) creates release requiring on-site response; consequence confined to utility loop outside main unit."
    },
    {
      "chain": "C3",
      "severity_class": "S3",
      "reason": "External fire (LOC-OLEFINS-UNIT) plus column relief valve failure causes backflow into EA-425A, adding hydrocarbon release to occupied outdoor area, worsening fire with potential for serious injuries/fatality on site."
    },
    {
      "chain": "C4",
      "severity_class": "S3",
      "reason": "Reverse flow from DA-406 overfills EA-425B shell with blocked relief path (HV-B-SIN, HV-B-SOUT closed), risking shell overpressure/rupture and significant hydrocarbon release to occupied Olefins unit (LOC-OLEFINS-UNIT)."
    },
    {
      "chain": "C5",
      "severity_class": "S2",
      "reason": "Propylene-water reaction in quench loop (UT-QW, LOC-QUENCH-LOOP) forms peroxides/flammable by-products with heat release, creating hazardous mixture in utility system requiring on-site response."
    }
  ]
}

